import os from "node:os";

// Use a quarter of the machine's RAM for the response cache
const budgetBytes = Math.floor(os.totalmem() * 0.25);

const cache = new Map<string, Buffer>();
let used = 0;

export function put(key: string, body: Buffer): void {
  if (used + body.length > budgetBytes) return; // full: skip caching
  cache.set(key, body);
  used += body.length;
}

